import{_ as t,a0 as d,w as o,s as r,I as n,x as a,a1 as i,A as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Linux 包管理器比较：dnf 和 apt | LCTT x X-CMD","titleTemplate":false,"description":"Linux 包管理器比较：dnf 和 apt | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 包管理器比较：dnf 和 apt | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 包管理器比较：dnf 和 apt | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210719 Linux package managers- dnf vs apt","title":"Linux 包管理器比较：dnf 和 apt","tag":"202107","desc":""},"relativePath":"202107/20210719 Linux package managers- dnf vs apt.md","filePath":"[post].md"}'),g={name:"202107/20210719 Linux package managers- dnf vs apt.md"};function h(u,s,c,k,b,f){const e=d("Link");return o(),r("div",null,[s[34]||(s[34]=n("h1",{id:"linux-包管理器比较-dnf-和-apt",tabindex:"-1"},[a("Linux 包管理器比较：dnf 和 apt "),n("a",{class:"header-anchor",href:"#linux-包管理器比较-dnf-和-apt","aria-label":"Permalink to “Linux 包管理器比较：dnf 和 apt”"},"​")],-1)),s[35]||(s[35]=n("blockquote",null,[n("p",null,"包管理器提供大致相同的功能：安装、管理和移除应用，但是它们还是有一些不一样的地方。")],-1)),s[36]||(s[36]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/27/083002sd5zzxu37yhiz6yc.jpg",alt:""})],-1)),n("p",null,[i(e,{href:"https://opensource.com/article/18/1/how-install-apps-linux"},{default:p(()=>[...s[0]||(s[0]=[a("在 Linux 系统上获取一个应用",-1)])]),_:1}),s[1]||(s[1]=a(" 有多种方式。例如，有新的 Flatpak 和容器方式，也有 DEB 和 RPM 这样一直以来经过考验的方式。",-1))]),s[37]||(s[37]=l(`<p>并没有一种通用的可以用于所有的操作系统的应用安装程序。如今，因为有无数的开发者发布软件，这导致了大部分的操作系统使用了应用商店（包括第一方和第三方）、拖放式安装，还有安装向导。不同的开发者对于他们发布的代码有不同的需求，这直接导致了他们所选择的安装方式的不同。</p><p>Linux 开创了一种通过命令行安装、管理、移除应用的包管理器的概念。<code>apt</code> 和 <code>dnf</code> 就是两种较为常见的包管理器。<code>apt</code> 命令是用来管理 DEB 格式的包，<code>dnf</code> 命令是用来管理 RPM 格式的包。这两种包管理器在理论上并不是完全互斥的，尽管在实际的实践中，Linux 发行版通常只会使用到其中的一种。理论上，这两种命令可以运行在同一个系统上，但是会造成安装包的重叠，版本控制也会更加困难，命令也会是冗余的。然而，如果你是在一个混合的 Linux 环境下工作，比如你的工作站运行的是一个发行版，同时需要与运行另外一种发行版的服务器进行交互，那么你最好同时掌握这两种包管理器。</p><h3 id="搜索应用" tabindex="-1">搜索应用 <a class="header-anchor" href="#搜索应用" aria-label="Permalink to “搜索应用”">​</a></h3><p>当你通过包管理器安装一个应用时，你需要先知道包的名称。通常，应用的名称和包的名称是一样的。<code>dnf</code> 和 <code>apt</code> 验证要安装的包名的过程是完全相同的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf search zsh</span></span>
<span class="line"><span>====== Name Exactly Matched: zsh ======</span></span>
<span class="line"><span>zsh.x86_64 : Powerful interactive shell</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>使用 <code>apt</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt search zsh</span></span>
<span class="line"><span>Sorting... Done</span></span>
<span class="line"><span>Full Text Search... Done</span></span>
<span class="line"><span>csh/stable 20110502-4+deb10u1 amd64</span></span>
<span class="line"><span>  Shell with C-like syntax</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ddgr/stable 1.6-1 all</span></span>
<span class="line"><span>  DuckDuckGo from the terminal</span></span>
<span class="line"><span></span></span>
<span class="line"><span>direnv/stable 2.18.2-2 amd64</span></span>
<span class="line"><span>  Utility to set directory specific environment variables</span></span>
<span class="line"><span></span></span>
<span class="line"><span>draai/stable 20180521-1 all</span></span>
<span class="line"><span>  Command-line music player for MPD</span></span>
<span class="line"><span>[...]</span></span></code></pre></div>`,7)),n("p",null,[s[3]||(s[3]=a("如果想通过 ",-1)),s[4]||(s[4]=n("code",null,"apt",-1)),s[5]||(s[5]=a(" 更快的获取相关的搜索结果，你可以使用 ",-1)),i(e,{href:"https://opensource.com/article/18/5/getting-started-regular-expressions"},{default:p(()=>[...s[2]||(s[2]=[a("正则表达式",-1)])]),_:1}),s[6]||(s[6]=a("：",-1))]),s[38]||(s[38]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt search ^zsh</span></span>
<span class="line"><span>Sorting... Done</span></span>
<span class="line"><span>Full Text Search... Done</span></span>
<span class="line"><span>zsh/stable 5.7.1-1 amd64</span></span>
<span class="line"><span>  shell with lots of features</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="查找应用程序包" tabindex="-1">查找应用程序包 <a class="header-anchor" href="#查找应用程序包" aria-label="Permalink to “查找应用程序包”">​</a></h3><p>有一些命令是与其它命令捆绑在一起的，都在一个包中。在这种情况下，你可以通过包管理器去了解哪个包提供了你需要的命令。<code>dnf</code> 和 <code>apt</code> 命令在如何搜索这类元数据上是有区别的。</p><p>使用 <code>dnf</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf provides pgrep</span></span>
<span class="line"><span>procps-ng-3.3.15-6.el8.x86_64 : System and process monitoring utilities</span></span>
<span class="line"><span>Repo        : baseos</span></span>
<span class="line"><span>Matched from:</span></span>
<span class="line"><span>Filename    : /usr/bin/pgrep</span></span></code></pre></div><p><code>apt</code> 命令使用子命令 <code>apt-file</code>。要使用 <code>apt-file</code>，你必须先安装它，然后提示它更新缓存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install apt-file</span></span>
<span class="line"><span>Reading package lists... Done</span></span>
<span class="line"><span>Building dependency tree      </span></span>
<span class="line"><span>Reading state information... Done</span></span>
<span class="line"><span>The following additional packages will be installed:</span></span>
<span class="line"><span>  libapt-pkg-perl libexporter-tiny-perl liblist-moreutils-perl libregexp-assemble-perl</span></span>
<span class="line"><span>The following NEW packages will be installed:</span></span>
<span class="line"><span>  apt-file libapt-pkg-perl libexporter-tiny-perl liblist-moreutils-perl libregexp-assemble-perl</span></span>
<span class="line"><span>0 upgraded, 5 newly installed, 0 to remove and 14 not upgraded.</span></span>
<span class="line"><span>Need to get 297 kB of archives.</span></span>
<span class="line"><span>After this operation, 825 kB of additional disk space will be used.</span></span>
<span class="line"><span>Do you want to continue? [Y/n] y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo apt-file update</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>你可以通过 <code>apt-file</code> 搜索命令。你可以使用此命令进行广泛的全局搜索，但假如你知道命令的执行路径，它会更准确：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-file search /usr/bin/pgrep</span></span>
<span class="line"><span>pgreplay: /usr/bin/pgreplay              </span></span>
<span class="line"><span>procps: /usr/bin/pgrep</span></span></code></pre></div><h3 id="安装应用程序" tabindex="-1">安装应用程序 <a class="header-anchor" href="#安装应用程序" aria-label="Permalink to “安装应用程序”">​</a></h3><p>使用<code>apt</code> 和 <code>dnf</code> 安装应用程序基本上是相同的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install zsh</span></span></code></pre></div><p>使用 <code>dnf</code>，你可以使用同样的方式来安装一个包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install zsh</span></span></code></pre></div>`,14)),n("p",null,[s[8]||(s[8]=a("许多基于 RPM 的发行版都具有组包安装的特性，它会将有时表面相关的应用程序收集到一个易于安装的目标中。例如，Fedora 中的 ",-1)),i(e,{href:"https://labs.fedoraproject.org/en/design-suite/"},{default:p(()=>[...s[7]||(s[7]=[a("Design Suite",-1)])]),_:1}),s[9]||(s[9]=a(" 组包就包含流行的创意应用程序。那些想要某一个创意应用程序的艺术家可能也想要类似的应用程序，选择安装一整个组包一个简单而快速的方法，可以合理地开始建立一个数字工作室。你可以通过 ",-1)),s[10]||(s[10]=n("code",null,"group list",-1)),s[11]||(s[11]=a(" 来查看可用的组包（使用 ",-1)),s[12]||(s[12]=n("code",null,"-v",-1)),s[13]||(s[13]=a(" 来查看不带空格的组名）：",-1))]),s[39]||(s[39]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf group list -v</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Available Groups:</span></span>
<span class="line"><span>   Container Management (container-management)</span></span>
<span class="line"><span>   RPM Development Tools (rpm-development-tools)</span></span>
<span class="line"><span>   Design Suite (design-suite)</span></span>
<span class="line"><span>   Development Tools (development)</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>使用 <code>group install</code> 子命令安装 RPM 组包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf group install design-suite</span></span></code></pre></div><p>你可以使用 <code>@</code> 符号来减少输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install @design-suite</span></span></code></pre></div><h3 id="更新应用程序" tabindex="-1">更新应用程序 <a class="header-anchor" href="#更新应用程序" aria-label="Permalink to “更新应用程序”">​</a></h3><p>使用包管理器的一个优点是，它知道所有已经安装的应用。这样你不必去寻找应用程序的更新版本。相反，你可以通过包管理器去获取更新的版本。</p><p><code>dnf</code> 和 <code>apt</code> 使用的子命令略有不同。因为 <code>apt</code> 保存了一个需要定期更新的缓存信息，它使用 <code>upgrade</code> 子命令来更新应用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt upgrade</span></span></code></pre></div><p>相比之下，<code>dnf</code> 命令在你每次使用时都会更新元信息，所以 <code>update</code> 和 <code>upgrade</code> 子命令是可以互换的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf upgrade</span></span></code></pre></div><p>这等同于：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf update</span></span></code></pre></div><h3 id="移除应用程序" tabindex="-1">移除应用程序 <a class="header-anchor" href="#移除应用程序" aria-label="Permalink to “移除应用程序”">​</a></h3><p>如果你曾经尝试在任何一个平台上手动删除一个应用程序，你就会知道，应用程序删除后，在硬盘上会残留各种文件，比如首选项文件、数据或图标。所以包管理器的另一个优点是，包管理器管理着包中安装的每一个文件，可以很方便的删除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf remove zsh</span></span></code></pre></div><p><code>remove</code> 子命令也适用于 <code>apt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt remove zsh</span></span></code></pre></div><p>使用 <code>apt</code> 命令删除一个包并不会删除已修改的用户配置文件，以防你意外删除了包。如果你想通过 <code>apt</code> 命令删除一个应用及其配置文件，请在你之前删除过的应用程序上使用 <code>purge</code> 子命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt purge zsh</span></span></code></pre></div><p><code>apt</code> 和 <code>dnf</code> 都不会删除家目录中的数据和配置文件（即使使用 <code>purge</code> 子命令）。如果想要从家目录中删除数据，你必须手动操作（通常你可以在 <code>~/.config</code> 和 <code>~/.local</code> 文件中找到）。</p><h3 id="了解包管理" tabindex="-1">了解包管理 <a class="header-anchor" href="#了解包管理" aria-label="Permalink to “了解包管理”">​</a></h3><p>无论你选择的发行版支持的是 <code>apt</code> 还是 <code>dnf</code>，这些命令的用途大致相同。它们可以帮助你安装、更新和移除包。这两种包管理器是目前最通用的包管理器。它们的语法元素在很大程度上是相同的，所以在两者之间切换非常容易。</p><p><code>apt</code> 和 <code>dnf</code> 还有一些高级功能，例如仓库管理，但这些功能并不像你使用 <code>search</code> 和 <code>install</code> 那样频繁。</p>`,24)),n("p",null,[s[16]||(s[16]=a("无论你更经常使用哪种包管理器，你都可以下载我们的 ",-1)),i(e,{href:"https://opensource.com/downloads/apt-cheat-sheet"},{default:p(()=>[...s[14]||(s[14]=[a("apt 备忘单",-1)])]),_:1}),s[17]||(s[17]=a(" 和 ",-1)),i(e,{href:"https://opensource.com/downloads/dnf-cheat-sheet"},{default:p(()=>[...s[15]||(s[15]=[a("dnf 备忘单",-1)])]),_:1}),s[18]||(s[18]=a("，以便你在最需要的时候可以查询使用语法。",-1))]),s[40]||(s[40]=n("hr",null,null,-1)),n("p",null,[s[20]||(s[20]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/7/dnf-vs-apt"},{default:p(()=>[...s[19]||(s[19]=[a("https://opensource.com/article/21/7/dnf-vs-apt",-1)])]),_:1})]),n("p",null,[s[25]||(s[25]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[21]||(s[21]=[a("Seth Kenlon",-1)])]),_:1}),s[26]||(s[26]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[22]||(s[22]=[a("lujun9972",-1)])]),_:1}),s[27]||(s[27]=a(" 译者：",-1)),i(e,{href:"https://github.com/perfiffer"},{default:p(()=>[...s[23]||(s[23]=[a("perfiffer",-1)])]),_:1}),s[28]||(s[28]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[24]||(s[24]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[29]||(s[29]=[a("LCTT",-1)])]),_:1}),s[32]||(s[32]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[30]||(s[30]=[a("Linux中国",-1)])]),_:1}),s[33]||(s[33]=a(" 荣誉推出",-1))])])}const v=t(g,[["render",h]]);export{x as __pageData,v as default};
